import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> cellsInRange(String s) {
        List<String> cells = new ArrayList<>();
        for (char column = s.charAt(0); column <= s.charAt(3); column++) {
            for (char row = s.charAt(1); row <= s.charAt(4); row++) {
                cells.add("" + column + row);
            }
        }
        return cells;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> cellsInRange(String s) {
        int columnCount = s.charAt(3) - s.charAt(0) + 1;
        int rowCount = s.charAt(4) - s.charAt(1) + 1;
        List<String> cells = new ArrayList<>(columnCount * rowCount);
        for (char column = s.charAt(0); column <= s.charAt(3); column++) {
            for (char row = s.charAt(1); row <= s.charAt(4); row++) {
                StringBuilder builder = new StringBuilder(2);
                builder.append(column).append(row);
                cells.add(builder.toString());
            }
        }
        return cells;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> cellsInRange(String s) {
        List<String> cells = new ArrayList<>();
        char[] cell = new char[2];
        for (char column = s.charAt(0); column <= s.charAt(3); column++) {
            cell[0] = column;
            for (char row = s.charAt(1); row <= s.charAt(4); row++) {
                cell[1] = row;
                cells.add(new String(cell));
            }
        }
        return cells;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> cellsInRange(String s) {
        int columnCount = s.charAt(3) - s.charAt(0) + 1;
        int rowCount = s.charAt(4) - s.charAt(1) + 1;
        List<String> cells = new ArrayList<>(columnCount * rowCount);
        for (int index = 0; index < columnCount * rowCount; index++) {
            char column = (char) (s.charAt(0) + index / rowCount);
            char row = (char) (s.charAt(1) + index % rowCount);
            cells.add("" + column + row);
        }
        return cells;
    }
}
